/* 50 BOLOS SEM GLÚTEN. Formato ingrediente: "quantidade|nome". Usa a função R de content/paes.js. Lotes adicionados em sequência (veja PROGRESS.md). */
const RB=(num,...a)=>({...R(num,...a),id:"bolos"+num});
const RBC=(cook,num,...a)=>({...RB(num,...a),cook});
window.BOLOS=[
RB(1,"Bolo simples de arroz e fécula","Bolos simples","Bolo básico de baunilha, de miolo macio e sabor neutro, para o café e para servir com geleia ou fruta.","1 bolo de 22 cm de diâmetro (10 fatias)",15,40,"180 °C",
["200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","200 g (1 xícara)|açúcar","3 unidades|ovos","120 ml (1/2 xícara)|óleo de girassol","240 ml (1 xícara)|leite integral","12 g (1 colher de sopa rasa)|fermento químico em pó","5 ml (1 colher de chá)|extrato de baunilha","1 pitada|sal","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com a manteiga uma forma redonda de 22 cm de diâmetro e 6 cm de altura e polvilhe com a farinha de arroz para untar.","Peneire juntos a farinha de arroz, a fécula, o fermento e o sal.","Na batedeira, bata os ovos com o açúcar por 4 minutos, até a mistura ficar clara e dobrar de volume.","Com a batedeira em velocidade baixa, junte o óleo, o leite e a baunilha e bata só até misturar.","Acrescente os ingredientes secos em três vezes, mexendo com um fouet a cada adição. A massa deve ficar lisa e fluida, escorrendo da colher em fita contínua.","Despeje na forma e bata a forma duas vezes na bancada para soltar as bolhas grandes.","Asse por 35 a 40 minutos, sem abrir o forno nos primeiros 25 minutos. O bolo está pronto quando o topo estiver dourado, as bordas começarem a se soltar da forma e um palito sair limpo do centro.","Espere 10 minutos, solte as laterais com uma faca, desenforme sobre uma grade e deixe esfriar por completo antes de cortar."],
["A farinha de arroz pode deixar a massa levemente granulosa. Peneirar e bater bem os ovos com o açúcar ajuda a obter um miolo mais macio.","Não troque a fécula de batata por polvilho na mesma medida: o polvilho muda a textura e deixa o bolo mais elástico.","Confira no rótulo o fermento, a baunilha e a fécula, e evite utensílios que tenham tocado farinha de trigo."],
"Até 3 dias em recipiente fechado, em temperatura ambiente. Em clima quente, guarde na geladeira.","bolo básico baunilha arroz fécula batata simples café"),
RB(2,"Bolo de iogurte com furo","Bolos simples","Bolo úmido e levemente firme, assado em forma com furo no centro, feito com iogurte natural.","1 bolo de 22 cm com furo central (12 fatias)",15,38,"180 °C",
["180 g (1 e 1/5 de xícara)|farinha de arroz branca","120 g (3/4 de xícara)|polvilho doce","200 g (1 xícara)|açúcar","170 g (1 pote)|iogurte natural integral","60 ml (1/4 de xícara)|leite integral","100 ml|óleo de girassol","3 unidades|ovos","12 g (1 colher de sopa rasa)|fermento químico em pó","5 ml (1 colher de chá)|extrato de baunilha","1 colher de sopa|manteiga, para untar","1 colher de sopa|polvilho doce, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma de 22 cm com furo central e polvilhe com o polvilho doce.","Misture a farinha de arroz, o polvilho e o fermento numa tigela grande.","No liquidificador, bata os ovos, o açúcar, o iogurte, o leite, o óleo e a baunilha por 1 minuto, até ficar homogêneo.","Despeje o líquido sobre os ingredientes secos e misture com o fouet só até desaparecerem os pontos de farinha. A massa deve ficar lisa e um pouco mais espessa que massa de panqueca.","Passe a massa para a forma e alise o topo.","Asse por 35 a 38 minutos, até dourar e um palito sair limpo.","Deixe amornar por 10 minutos na forma, desenforme e esfrie sobre uma grade."],
["O polvilho doce deixa o miolo ligeiramente elástico. É uma característica do bolo, não um defeito.","Se quiser variar, troque a baunilha por raspas de laranja sem a parte branca.","Confira no rótulo o iogurte, o polvilho e o fermento."],
"Até 4 dias em recipiente fechado, em local fresco. Pode ser congelado em fatias por até 1 mês.","iogurte natural furo polvilho doce simples lanche"),
RB(3,"Pão de ló sem glúten","Bolos simples","Bolo aerado de ovos, sem fermento químico, de miolo leve e esponjoso, ótimo para recheios e coberturas.","1 bolo de 22 cm de diâmetro (10 fatias)",25,28,"180 °C",
["5 unidades (cerca de 250 g)|ovos em temperatura ambiente","150 g (3/4 de xícara)|açúcar","60 g (1/2 xícara)|amido de milho","40 g (1/4 de xícara)|farinha de arroz branca","5 ml (1 colher de chá)|extrato de baunilha","1 pitada|sal","1 colher de chá|manteiga, para untar o fundo da forma"],
["Preaqueça o forno a 180 °C. Unte apenas o fundo de uma forma redonda de 22 cm, de fundo removível, e forre com papel-manteiga. Não unte as laterais, para o bolo poder subir agarrando na forma.","Peneire duas vezes juntos o amido de milho, a farinha de arroz e o sal.","Na batedeira, bata os ovos inteiros com o açúcar em velocidade alta por 8 a 10 minutos, até o creme triplicar de volume, ficar bem claro e formar uma fita grossa que se mantém por alguns segundos quando levantar o batedor.","Junte a baunilha e bata mais 20 segundos.","Peneire os secos sobre o creme em três vezes e misture com uma espátula, de baixo para cima, com movimentos delicados, só até incorporar. Não use a batedeira nesta etapa.","Despeje na forma e asse por 25 a 28 minutos, sem abrir o forno. O bolo está pronto quando o topo estiver dourado e firme ao toque leve.","Passe uma faca nas laterais, desenforme ainda morno sobre uma grade e retire o papel. Deixe esfriar por completo."],
["O volume do bolo depende de bater os ovos por tempo suficiente. Se o creme não formar fita, continue batendo por mais 2 minutos.","Se a espátula bater com força, o ar escapa e o bolo fica baixo. Misture devagar.","Confira no rótulo o amido de milho e a farinha de arroz."],
"Até 2 dias em recipiente fechado. Melhor consumido no dia, ou recheado e coberto logo antes de servir.","pão de ló ovos aerado esponjoso sem fermento recheio base"),
RB(4,"Bolo de leite quente","Bolos simples","Bolo de massa macia e úmida, feito com leite e manteiga aquecidos, de sabor delicado.","1 bolo de 22 cm de diâmetro (10 fatias)",20,35,"180 °C",
["3 unidades|ovos","200 g (1 xícara)|açúcar","150 g (1 xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","250 ml (1 xícara)|leite integral","60 g (3 colheres de sopa)|manteiga","12 g (1 colher de sopa rasa)|fermento químico em pó","5 ml (1 colher de chá)|extrato de baunilha","1 pitada|sal","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte e polvilhe com farinha de arroz uma forma redonda de 22 cm.","Numa panelinha, aqueça o leite com a manteiga até a manteiga derreter e o leite começar a soltar fumaça. Não deixe ferver. Reserve.","Peneire a farinha de arroz, a fécula e o sal.","Na batedeira, bata os ovos com o açúcar por 5 minutos, até ficarem claros e volumosos. Junte a baunilha.","Acrescente os ingredientes secos e misture em velocidade baixa. A massa fica bem espessa nesta fase.","Sem parar de bater em velocidade baixa, despeje o leite quente em fio fino. A massa vai ficar fluida e lisa.","Peneire o fermento sobre a massa e misture delicadamente com a espátula.","Despeje na forma e asse por 33 a 35 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar numa grade."],
["O leite quente cozinha parte do amido e deixa o miolo mais úmido. Por isso o fermento entra por último, para não perder força.","Se o leite ferver, deixe amornar por 2 minutos antes de juntar, para não cozinhar os ovos.","Confira no rótulo a manteiga (versões com aditivos) e o fermento."],
"Até 3 dias em recipiente fechado. Pode ser congelado em fatias por até 1 mês.","leite quente manteiga clássico caseiro fofinho"),
RB(5,"Bolo de mel com calda","Bolos simples","Bolo de forma inglesa, de cor dourada e perfume de mel, finalizado com calda leve.","1 bolo de 25 × 11 cm (10 fatias)",15,45,"170 °C",
["3 unidades|ovos","100 g (1/2 xícara, bem cheia)|açúcar mascavo","120 g (1/3 de xícara)|mel, mais 30 g para a calda","100 ml|óleo de girassol","200 ml|leite integral","150 g (1 xícara)|farinha de arroz integral","100 g (2/3 de xícara)|polvilho doce","10 g (2 colheres de chá)|fermento químico em pó","2 g (1/2 colher de chá)|bicarbonato de sódio","1 colher de sopa|água quente, para a calda","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 170 °C. Unte com manteiga e polvilhe com farinha de arroz uma forma de 25 × 11 cm.","Peneire a farinha integral, o polvilho, o fermento e o bicarbonato. Devolva ao recipiente os farelos que ficarem na peneira.","Bata os ovos com o açúcar mascavo por 3 minutos. Junte os 120 g de mel, o óleo e o leite e misture.","Acrescente os secos e mexa com o fouet até a massa ficar lisa, mais fluida que massa de bolo comum.","Despeje na forma e asse por 40 a 45 minutos. O topo deve ficar bem dourado e um palito sair limpo.","Enquanto o bolo asse, misture os 30 g de mel restantes com a água quente.","Retire o bolo, espere 5 minutos, desenforme e pincele a calda sobre o bolo ainda morno. Deixe esfriar antes de cortar."],
["O mel doura mais rápido que o açúcar. Se o topo escurecer antes do tempo, cubra com papel-alumínio.","O mel não deve ser dado a crianças menores de 1 ano.","Confira no rótulo o mel, a farinha integral e o fermento."],
"Até 4 dias em recipiente fechado, em local fresco. A calda deixa o bolo mais úmido no segundo dia.","mel mascavo integral forma inglesa calda lanche"),
RB(6,"Bolo de requeijão","Bolos simples","Bolo de miolo cremoso e macio, enriquecido com requeijão e manteiga, assado em forma com furo.","1 bolo de 22 cm com furo central (12 fatias)",20,38,"180 °C",
["200 g (1 copo pequeno)|requeijão cremoso","100 ml|leite integral","3 unidades|ovos","180 g (cerca de 1 xícara)|açúcar","60 g (3 colheres de sopa)|manteiga derretida","180 g (1 e 1/5 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","5 ml (1 colher de chá)|extrato de baunilha","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte e polvilhe com farinha de arroz uma forma de 22 cm com furo central.","Peneire a farinha de arroz, a fécula e o fermento.","Bata os ovos com o açúcar por 3 minutos. Junte o requeijão, o leite, a manteiga derretida (morna) e a baunilha e misture até ficar homogêneo.","Acrescente os secos em duas vezes e mexa só até incorporar. A massa deve ficar espessa e cremosa, caindo da colher em blocos moles.","Despeje na forma e alise o topo.","Asse por 36 a 38 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar na grade."],
["Use requeijão cremoso de copo, que é mais úmido que o requeijão em barra.","Se o requeijão estiver muito frio, deixe 15 minutos fora da geladeira para misturar sem grumos.","Confira no rótulo o requeijão, que pode conter amidos e aditivos."],
"Até 4 dias na geladeira, em recipiente fechado. Retire 20 minutos antes de servir.","requeijão cremoso furo manteiga macio queijo"),
RB(7,"Bolo de chocolate de liquidificador","Chocolate e cacau","Bolo de chocolate fofinho, feito quase todo no liquidificador, com sabor intenso de cacau.","1 bolo de 22 cm de diâmetro (10 fatias)",15,38,"180 °C",
["3 unidades|ovos","120 ml (1/2 xícara)|óleo de girassol","240 ml (1 xícara)|leite integral","220 g (1 e 1/10 de xícara)|açúcar","40 g (1/2 xícara)|cacau em pó 100%","180 g (1 e 1/5 de xícara)|farinha de arroz branca","80 g (1/2 xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","1 pitada|sal","1 colher de sopa|manteiga, para untar","1 colher de sopa|cacau em pó, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com cacau em pó.","No liquidificador, bata os ovos, o óleo, o leite, o açúcar e o cacau por 2 minutos, até ficar liso e sem pontos de cacau.","Peneire a farinha de arroz, a fécula e o sal sobre uma tigela grande.","Despeje o líquido do liquidificador sobre os secos e misture com o fouet até ficar homogêneo. A massa deve ficar fluida, parecida com massa de panqueca grossa.","Junte o fermento e misture com poucos movimentos.","Despeje na forma e asse por 36 a 38 minutos. O bolo está pronto quando o centro estiver firme ao toque e um palito sair limpo ou com poucas migalhas secas.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["Bater a farinha no liquidificador com os líquidos pode deixar o bolo borrachudo. Por isso os secos são misturados à parte.","Use cacau em pó 100%. Achocolatado em pó tem açúcar e outros ingredientes e muda a receita.","Confira no rótulo o cacau e o fermento."],
"Até 4 dias em recipiente fechado. Congela bem em fatias por até 1 mês.","chocolate cacau liquidificador fofinho aniversário cacau em pó"),
RB(8,"Bolo molhadinho de chocolate com brigadeiro","Chocolate e cacau","Bolo de chocolate feito com água fervente, de miolo bem úmido, coberto com brigadeiro cremoso de panela.","1 bolo de 22 cm de diâmetro (10 fatias)",25,35,"180 °C",
["2 unidades|ovos","220 g (1 e 1/10 de xícara)|açúcar","80 ml|óleo de girassol","40 g (1/2 xícara)|cacau em pó 100%","220 ml|água fervente","180 g (1 e 1/5 de xícara)|farinha de arroz branca","80 g (2/3 de xícara)|amido de milho","10 g (2 colheres de chá)|fermento químico em pó","2 g (1/2 colher de chá)|bicarbonato de sódio","395 g (1 lata)|leite condensado","30 g (3 colheres de sopa)|cacau em pó 100%, para a cobertura","20 g (1 colher de sopa)|manteiga, para a cobertura","1 colher de sopa|manteiga, para untar","1 colher de sopa|cacau em pó, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte uma forma redonda de 22 cm e polvilhe com cacau.","Numa tigela, dissolva os 40 g de cacau na água fervente e mexa até ficar liso. Espere amornar por 10 minutos.","Em outra tigela, misture com o fouet os ovos, o açúcar e o óleo por 1 minuto. Junte o chocolate morno.","Peneire por cima a farinha de arroz, o amido, o fermento e o bicarbonato e mexa até a massa ficar lisa. Ela será bem líquida, mais fina que a massa de um bolo comum.","Despeje na forma e asse por 33 a 35 minutos, até o centro firmar e um palito sair limpo ou com poucas migalhas úmidas.","Espere 10 minutos, desenforme e deixe esfriar até ficar morno.","Para a cobertura, leve ao fogo baixo o leite condensado, os 30 g de cacau e a manteiga, mexendo sem parar por 8 a 10 minutos, até aparecer o fundo da panela ao passar a colher.","Deixe a cobertura amornar por 5 minutos e espalhe sobre o bolo."],
["A massa líquida é esperada nesta receita. Ela rende um miolo úmido.","Se o brigadeiro endurecer, junte 1 colher de sopa de leite e aqueça por 30 segundos.","Confira no rótulo o leite condensado, o cacau e o fermento."],
"Até 3 dias em recipiente fechado, em local fresco. Com a cobertura, mantenha na geladeira em dias quentes.","brigadeiro cobertura chocolate molhadinho água quente leite condensado festa"),
RB(9,"Bolo de chocolate sem farinha","Chocolate e cacau","Bolo denso e cremoso de chocolate, feito apenas com ovos, manteiga e chocolate, sem nenhuma farinha.","1 bolo de 20 cm (8 fatias)",25,28,"180 °C",
["200 g|chocolate meio amargo (mínimo 50% de cacau) picado","120 g (6 colheres de sopa)|manteiga","4 unidades|ovos, separados","120 g (1/2 xícara e 2 colheres de sopa)|açúcar","20 g (2 colheres de sopa)|cacau em pó 100%","1 pitada|sal","1 colher de sopa|manteiga, para untar","1 colher de sopa|cacau em pó, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte uma forma de 20 cm de fundo removível, forre o fundo com papel-manteiga e polvilhe com cacau.","Derreta o chocolate com a manteiga em banho-maria ou no micro-ondas, em pulsos de 30 segundos, mexendo entre eles. Deixe amornar.","Bata as gemas com metade do açúcar por 3 minutos, até clarearem. Junte o chocolate morno e o cacau e misture.","Em outra tigela limpa e seca, bata as claras com o sal até espumarem, junte o restante do açúcar aos poucos e bata até picos moles.","Incorpore um terço das claras ao chocolate para soltar a massa e misture com firmeza. Junte o restante com a espátula, de baixo para cima, até não restarem riscos brancos.","Despeje na forma e asse por 25 a 28 minutos, até as bordas firmarem e o centro ainda ficar levemente trêmulo.","Deixe esfriar 20 minutos na forma. O bolo vai baixar um pouco no centro, o que é normal. Desenforme com cuidado."],
["Prefira chocolate em barra de boa qualidade. Gotas e chocolates com muita gordura vegetal derretem de forma diferente.","O bolo fica mais firme e fácil de cortar depois de 2 horas na geladeira.","Confira no rótulo o chocolate e o cacau, e verifique a declaração sobre glúten."],
"Até 5 dias na geladeira, em recipiente fechado. Sirva em temperatura ambiente.","chocolate sem farinha flourless denso cremoso ovos manteiga"),
RB(10,"Bolo inglês de chocolate com gotas","Chocolate e cacau","Bolo de forma inglesa feito pelo método da manteiga batida com açúcar, de miolo denso e macio, com gotas de chocolate.","1 bolo de 25 × 11 cm (10 fatias)",25,45,"170 °C",
["100 g (1/2 xícara)|manteiga em temperatura ambiente","150 g (3/4 de xícara)|açúcar mascavo","3 unidades|ovos","150 g (1 pote)|iogurte natural integral","30 g (1/3 de xícara)|cacau em pó 100%","150 g (1 xícara)|farinha de arroz branca","80 g (1/2 xícara)|fécula de batata","10 g (2 colheres de chá)|fermento químico em pó","80 g|gotas de chocolate meio amargo","1 colher de chá|amido de milho, para enfarinhar as gotas","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 170 °C. Unte e polvilhe com farinha de arroz uma forma de 25 × 11 cm.","Peneire a farinha de arroz, a fécula, o cacau e o fermento.","Na batedeira, bata a manteiga com o açúcar mascavo por 4 a 5 minutos, até virar um creme claro e fofo.","Junte os ovos um a um, batendo 1 minuto após cada um.","Acrescente os secos em três vezes, alternando com o iogurte em duas vezes, sempre em velocidade baixa. A massa deve ficar espessa e cremosa, caindo da colher em blocos.","Misture as gotas de chocolate com o amido de milho e incorpore à massa com a espátula.","Despeje na forma, alise o topo e asse por 42 a 45 minutos, até um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar em grade antes de fatiar."],
["Passar as gotas no amido ajuda a mantê-las distribuídas, em vez de afundarem.","Se a massa talhar ao juntar os ovos, o ingrediente está frio demais. Junte uma colher dos secos e continue.","Confira no rótulo as gotas de chocolate e o cacau."],
"Até 4 dias em recipiente fechado. Fatias podem ser congeladas por até 1 mês.","chocolate gotas forma inglesa manteiga iogurte mascavo lanche"),
RB(11,"Bolo de chocolate e beterraba","Chocolate e cacau","Bolo de chocolate muito úmido, em que a beterraba cozida dá cor e maciez sem aparecer no sabor.","1 bolo de 22 cm de diâmetro (10 fatias)",25,38,"180 °C",
["200 g (1 beterraba média)|beterraba cozida e picada","3 unidades|ovos","100 ml|óleo de girassol","80 ml|leite integral","200 g (1 xícara)|açúcar","40 g (1/2 xícara)|cacau em pó 100%","180 g (1 e 1/5 de xícara)|farinha de arroz branca","80 g (1/2 xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","5 ml (1 colher de chá)|extrato de baunilha","1 colher de sopa|manteiga, para untar","1 colher de sopa|cacau em pó, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com cacau.","No liquidificador, bata a beterraba, os ovos, o óleo, o leite, o açúcar e a baunilha por 2 a 3 minutos, até não restarem pedaços visíveis.","Junte o cacau e bata mais 30 segundos.","Peneire a farinha de arroz e a fécula sobre uma tigela grande, despeje o líquido e misture com o fouet até ficar liso. A massa deve ficar espessa e fluida, de cor escura e brilhante.","Acrescente o fermento e misture com poucos movimentos.","Despeje na forma e asse por 36 a 38 minutos, até o centro firmar e um palito sair limpo ou com poucas migalhas úmidas.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["Use beterraba cozida no vapor ou na água e bem escorrida. Beterraba em conserva tem sal e acidez que mudam o resultado.","A cor da massa crua é vermelho-escura. Depois de assada, fica de um marrom intenso.","Confira no rótulo o cacau e o fermento."],
"Até 4 dias em recipiente fechado. O bolo fica ainda mais úmido no segundo dia.","chocolate beterraba legumes úmido cacau liquidificador"),
RB(12,"Bolo mármore de baunilha e cacau","Chocolate e cacau","Bolo de duas massas, uma de baunilha e outra de cacau, que formam um desenho marmorizado na fatia.","1 bolo de 22 cm com furo central (12 fatias)",25,42,"180 °C",
["3 unidades|ovos","200 g (1 xícara)|açúcar, mais 20 g para a massa de cacau","120 ml (1/2 xícara)|óleo de girassol","240 ml (1 xícara)|leite integral, mais 60 ml para a massa de cacau","200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","5 ml (1 colher de chá)|extrato de baunilha","30 g (1/3 de xícara)|cacau em pó 100%","1 pitada|sal","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma de 22 cm com furo central e polvilhe com farinha de arroz.","Peneire a farinha de arroz, a fécula, o fermento e o sal.","Bata os ovos com os 200 g de açúcar por 4 minutos, até ficarem claros. Junte o óleo, os 240 ml de leite e a baunilha e misture.","Acrescente os secos em três vezes, mexendo com o fouet até ficar liso.","Separe cerca de 1/3 da massa (aproximadamente 1 xícara) numa tigela. Junte a ela o cacau, os 20 g de açúcar e os 60 ml de leite e misture. Essa massa deve ficar com consistência parecida com a da massa clara.","Despeje a massa clara na forma e coloque a massa de cacau por cima, em colheradas espaçadas.","Com um garfo, faça 3 voltas lentas, em forma de espiral, de baixo para cima. Não misture demais para manter o desenho.","Asse por 40 a 42 minutos, até um palito sair limpo. Espere 10 minutos, desenforme e deixe esfriar numa grade."],
["Se a massa de cacau ficar mais espessa que a clara, junte 1 colher de sopa de leite até igualar a consistência.","Poucas voltas com o garfo dão um desenho mais definido. Muitas voltas deixam o bolo uniforme.","Confira no rótulo o cacau, o fermento e a baunilha."],
"Até 4 dias em recipiente fechado. Congela bem em fatias por até 1 mês.","mármore marmorizado baunilha chocolate duas massas furo"),
RB(13,"Bolo de banana com canela","Frutas","Bolo úmido e perfumado de bananas bem maduras, com sabor de café da tarde e topo caramelizado.","1 bolo de 25 × 11 cm (10 fatias)",20,48,"170 °C",
["300 g (3 bananas nanicas maduras)|banana amassada com garfo","2 unidades|ovos","100 g (1/2 xícara)|açúcar mascavo","80 ml|óleo de girassol","60 ml|leite integral","150 g (1 xícara)|farinha de arroz branca","80 g (2/3 de xícara)|amido de milho","12 g (1 colher de sopa rasa)|fermento químico em pó","4 g (1 colher de chá)|canela em pó","1 pitada|sal","1 unidade|banana cortada ao meio no sentido do comprimento, para o topo","1 colher de sopa|açúcar, para o topo","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 170 °C. Unte com manteiga uma forma de 25 × 11 cm e polvilhe com farinha de arroz.","Numa tigela, misture a banana amassada, os ovos, o açúcar mascavo, o óleo e o leite com o fouet.","Peneire por cima a farinha de arroz, o amido, o fermento, a canela e o sal.","Mexa até a massa ficar homogênea. Ela deve ser espessa e cair da colher em blocos moles.","Despeje na forma e acomode as duas metades de banana sobre a massa, com a parte cortada voltada para cima. Polvilhe o açúcar do topo.","Asse por 45 a 48 minutos. O topo deve dourar e um palito sair limpo do centro, longe da banana.","Espere 10 minutos, desenforme e deixe esfriar numa grade antes de fatiar."],
["Quanto mais madura a banana, mais doce e úmido o bolo. Bananas ainda verdes deixam o miolo seco e pouco saboroso.","Se o topo escurecer muito, cubra com papel-alumínio nos últimos 15 minutos.","Confira no rótulo a canela e o fermento."],
"Até 3 dias em recipiente fechado. Pode ser congelado em fatias por até 1 mês.","banana nanica canela forma inglesa lanche mascavo"),
RB(14,"Bolo de maçã com topo de fatias","Frutas","Bolo macio com cubos de maçã na massa e fatias de maçã douradas por cima.","1 bolo de 22 cm de diâmetro (10 fatias)",25,42,"180 °C",
["2 unidades (cerca de 300 g)|maçãs em cubos de 1 cm, com casca","1 unidade (média, para o topo)|maçã em fatias finas","3 unidades|ovos","150 g (3/4 de xícara)|açúcar","100 ml|óleo de girassol","100 ml|leite integral","200 g (1 e 1/3 de xícara)|farinha de arroz branca","80 g (1/2 xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","2 g (1/2 colher de chá)|canela em pó, mais 2 g para o topo","1 colher de sopa|açúcar, para o topo","1 colher de sopa|suco de limão","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com farinha de arroz.","Misture os cubos de maçã com o suco de limão para não escurecerem.","Bata os ovos com o açúcar por 3 minutos. Junte o óleo e o leite.","Peneire a farinha de arroz, a fécula, o fermento e 2 g de canela sobre a mistura e mexa até ficar liso. A massa deve ficar espessa.","Junte os cubos de maçã e misture delicadamente.","Despeje na forma e distribua as fatias de maçã por cima, ligeiramente sobrepostas. Misture o açúcar do topo com os 2 g de canela restantes e polvilhe.","Asse por 40 a 42 minutos, até um palito sair limpo e as fatias ficarem douradas.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["Use maçãs firmes, como a fuji ou a gala. Maçãs muito macias desmancham no forno.","Os cubos de maçã soltam água. Por isso a massa é mais firme que a de um bolo comum.","Confira no rótulo a canela e o fermento."],
"Até 3 dias em recipiente fechado, em local fresco. Em clima quente, guarde na geladeira.","maçã fuji gala canela fatias fruta topo"),
RB(15,"Bolo invertido de abacaxi","Frutas","Bolo com caramelo e rodelas de abacaxi no fundo da forma, que fica por cima ao desenformar.","1 bolo de 24 cm de diâmetro (10 fatias)",35,40,"180 °C",
["100 g (1/2 xícara)|açúcar, para o caramelo","30 ml (2 colheres de sopa)|água, para o caramelo","30 g (1 colher de sopa cheia)|manteiga, para o caramelo","6 rodelas|abacaxi em calda, bem escorridas","3 unidades|ovos","150 g (3/4 de xícara)|açúcar, para a massa","80 ml|óleo de girassol","120 ml|calda do abacaxi","60 ml|leite integral","200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó"],
["Preaqueça o forno a 180 °C. Tenha à mão uma forma redonda de 24 cm de fundo fixo e laterais altas, sem untar.","Numa panela, leve ao fogo médio os 100 g de açúcar com a água, sem mexer, por 6 a 8 minutos, até virar um caramelo cor de âmbar. Tire do fogo, junte a manteiga e mexa até incorporar.","Despeje o caramelo no fundo da forma e espalhe rapidamente. Distribua as rodelas de abacaxi sobre o caramelo.","Bata os ovos com os 150 g de açúcar por 3 minutos. Junte o óleo, a calda do abacaxi e o leite.","Peneire a farinha de arroz, a fécula e o fermento sobre a mistura e mexa até ficar liso. A massa deve ser fluida.","Despeje a massa com cuidado sobre o abacaxi e asse por 38 a 40 minutos, até dourar e um palito sair limpo.","Espere 5 minutos, solte as laterais com uma faca e desenforme ainda morno sobre um prato, para o caramelo não grudar na forma."],
["Escorra bem o abacaxi e seque as rodelas com papel-toalha, para a massa não ficar encharcada.","Cuidado com o caramelo, que queima a pele. Use luvas ao desenformar.","Confira no rótulo o abacaxi em calda e o fermento."],
"Até 3 dias na geladeira, em recipiente fechado. Sirva em temperatura ambiente.","abacaxi invertido caramelo rodelas calda fruta"),
RB(16,"Bolo de morango com iogurte","Frutas","Bolo macio com pedaços de morango, que ficam suculentos e levemente ácidos no miolo.","1 bolo de 22 cm de diâmetro (10 fatias)",25,42,"180 °C",
["250 g|morangos lavados e picados em pedaços de 1 cm","8 g (1 colher de sopa rasa)|amido de milho, para os morangos","3 unidades|ovos","180 g (cerca de 1 xícara)|açúcar","80 g (4 colheres de sopa)|manteiga derretida","170 g (1 pote)|iogurte natural integral","50 ml|leite integral","180 g (1 e 1/5 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","5 ml (1 colher de chá)|extrato de baunilha","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com farinha de arroz.","Misture os morangos com o amido de milho e reserve. O amido ajuda a segurar o suco.","Bata os ovos com o açúcar por 3 minutos. Junte a manteiga derretida e morna, o iogurte, o leite e a baunilha.","Peneire a farinha de arroz, a fécula e o fermento sobre a mistura e mexa até ficar liso. A massa deve ser espessa e cremosa.","Incorpore metade dos morangos com a espátula.","Despeje na forma e distribua o restante dos morangos sobre a massa, pressionando levemente.","Asse por 40 a 42 minutos, até um palito sair limpo (sem tocar num pedaço de morango).","Espere 15 minutos, desenforme com cuidado e deixe esfriar numa grade."],
["Se os morangos estiverem muito aguados, seque-os bem com papel-toalha antes de picar.","O bolo fica mais úmido que os demais. Espere esfriar por completo antes de fatiar.","Confira no rótulo o iogurte e o amido de milho."],
"Até 3 dias na geladeira, em recipiente fechado. Não é indicado congelar, pois o morango solta água ao descongelar.","morango iogurte fruta vermelha suculento manteiga"),
RB(17,"Bolo de manga","Frutas","Bolo de cor dourada, com purê e pedaços de manga madura, de sabor tropical.","1 bolo de 22 cm de diâmetro (10 fatias)",25,42,"180 °C",
["200 g (cerca de 1 manga média)|manga madura em purê (batida no liquidificador)","150 g (cerca de 1 manga pequena)|manga firme em cubos de 1 cm","3 unidades|ovos","150 g (3/4 de xícara)|açúcar","100 ml|óleo de girassol","60 ml|leite integral","200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","1 colher de sopa|suco de limão","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com farinha de arroz.","Bata no liquidificador a manga madura com o suco de limão até virar um purê liso.","Numa tigela, bata os ovos com o açúcar por 3 minutos. Junte o óleo, o leite e o purê de manga.","Peneire a farinha de arroz, a fécula e o fermento sobre a mistura e mexa até ficar liso. A massa deve ser espessa e cair da colher em blocos moles.","Incorpore os cubos de manga firme.","Despeje na forma e asse por 40 a 42 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["Manga muito fibrosa deve ser batida por mais tempo ou passada na peneira.","Os cubos mais firmes mantêm a forma. Mangas muito moles desmancham na massa.","Confira no rótulo o fermento."],
"Até 3 dias em recipiente fechado. Em dias quentes, guarde na geladeira.","manga fruta tropical purê cubos verão"),
RB(18,"Bolo de pêssego em calda","Frutas","Bolo macio, aproveitando a calda do pêssego na massa, com fatias da fruta douradas no topo.","1 bolo de 22 cm de diâmetro (10 fatias)",25,42,"180 °C",
["1 lata (cerca de 450 g)|pêssego em calda, escorrido e com a calda reservada (8 metades)","3 unidades|ovos","150 g (3/4 de xícara)|açúcar","100 ml|óleo de girassol","100 ml|calda do pêssego","80 ml|leite integral","200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com farinha de arroz.","Seque as metades de pêssego com papel-toalha. Pique 4 metades em cubos pequenos e corte as outras 4 em fatias finas.","Bata os ovos com o açúcar por 3 minutos. Junte o óleo, a calda do pêssego e o leite.","Peneire a farinha de arroz, a fécula e o fermento sobre a mistura e mexa até ficar liso. A massa deve ser fluida, mas espessa o bastante para sustentar a fruta.","Incorpore os cubos de pêssego.","Despeje na forma e disponha as fatias por cima, em círculo.","Asse por 40 a 42 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar numa grade."],
["Seque bem a fruta. O excesso de calda faz os pedaços afundarem na massa.","A calda contém açúcar. Não aumente o açúcar da massa sem provar a doçura do pêssego.","Confira no rótulo o pêssego em calda, o fermento e a fécula."],
"Até 3 dias na geladeira, em recipiente fechado.","pêssego calda lata fruta fatias macio"),
RB(19,"Bolo de laranja de liquidificador","Cítricos","Bolo clássico de laranja, fofinho e perfumado, com glacê simples de suco de laranja.","1 bolo de 22 cm com furo central (12 fatias)",20,38,"180 °C",
["200 ml (suco de 2 laranjas)|suco de laranja","raspas de 1 laranja (só a parte alaranjada)|casca de laranja","3 unidades|ovos","120 ml (1/2 xícara)|óleo de girassol","220 g (1 e 1/10 de xícara)|açúcar","200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","120 g (cerca de 1 xícara)|açúcar de confeiteiro, para o glacê","30 ml (2 colheres de sopa)|suco de laranja, para o glacê","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma de 22 cm com furo central e polvilhe com farinha de arroz.","No liquidificador, bata o suco, as raspas, os ovos, o óleo e o açúcar por 2 minutos.","Peneire a farinha de arroz e a fécula numa tigela grande, despeje o líquido e misture com o fouet até ficar liso. A massa deve ficar fluida.","Junte o fermento e misture com poucos movimentos.","Despeje na forma e asse por 36 a 38 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar por completo.","Misture o açúcar de confeiteiro com os 30 ml de suco até obter um glacê espesso, que escorra devagar da colher. Espalhe sobre o bolo frio e espere firmar por 15 minutos."],
["Retire só a parte alaranjada da casca. A parte branca deixa um gosto amargo.","Confira no rótulo o açúcar de confeiteiro, pois algumas marcas contêm amido e aditivos.","Se o glacê ficar muito líquido, junte açúcar de confeiteiro, 1 colher de chá por vez."],
"Até 3 dias em recipiente fechado, em local fresco.","laranja suco raspas glacê cítrico liquidificador clássico"),
RB(20,"Bolo de limão com calda","Cítricos","Bolo de forma inglesa, de miolo macio e sabor marcante de limão, finalizado com calda ácida e doce.","1 bolo de 25 × 11 cm (10 fatias)",25,42,"170 °C",
["3 unidades|ovos","180 g (cerca de 1 xícara)|açúcar","80 g (4 colheres de sopa)|manteiga derretida","100 g (1/2 pote)|iogurte natural integral","60 ml (4 colheres de sopa)|suco de limão taiti","raspas de 2 limões taiti|casca de limão","170 g (1 e 1/10 de xícara)|farinha de arroz branca","80 g (1/2 xícara)|fécula de batata","10 g (2 colheres de chá)|fermento químico em pó","40 ml (cerca de 3 colheres de sopa)|suco de limão taiti, para a calda","60 g (cerca de 5 colheres de sopa)|açúcar, para a calda","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 170 °C. Unte com manteiga uma forma de 25 × 11 cm e polvilhe com farinha de arroz.","Bata os ovos com o açúcar e as raspas de limão por 4 minutos, até ficarem claros. Junte a manteiga derretida e morna, o iogurte e os 60 ml de suco de limão.","Peneire a farinha de arroz, a fécula e o fermento sobre a mistura e mexa até ficar liso. A massa deve ser espessa e cremosa.","Despeje na forma e asse por 40 a 42 minutos, até dourar e um palito sair limpo.","Enquanto o bolo asse, leve ao fogo baixo os 40 ml de suco com os 60 g de açúcar, mexendo, até o açúcar dissolver e a calda ferver por 1 minuto. Reserve.","Retire o bolo do forno e fure toda a superfície com um palito. Espalhe a calda quente aos poucos sobre o bolo ainda morno.","Espere 15 minutos, desenforme e deixe esfriar em grade antes de cortar."],
["O bolo precisa estar morno e a calda quente para a calda ser absorvida.","Para um sabor menos ácido, reduza o suco da calda para 30 ml e junte 10 ml de água.","Confira no rótulo o iogurte, o fermento e a fécula."],
"Até 4 dias em recipiente fechado. A calda deixa o bolo ainda mais úmido no segundo dia.","limão taiti calda ácido raspas forma inglesa cítrico"),
RB(21,"Bolo de tangerina com claras em neve","Cítricos","Bolo leve e aerado, de perfume suave de tangerina, feito com claras batidas à parte.","1 bolo de 22 cm de diâmetro (10 fatias)",30,35,"180 °C",
["3 unidades|ovos, separados","150 g (3/4 de xícara)|açúcar, para as gemas","50 g (1/4 de xícara)|açúcar, para as claras","80 ml|óleo de girassol","120 ml (suco de 2 a 3 tangerinas)|suco de tangerina","1 colher de sopa|raspas de tangerina","170 g (1 e 1/10 de xícara)|farinha de arroz branca","90 g (1/2 xícara e 1 colher de sopa)|fécula de batata","10 g (2 colheres de chá)|fermento químico em pó","1 pitada|sal","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com farinha de arroz.","Peneire a farinha de arroz, a fécula e o fermento.","Bata as gemas com os 150 g de açúcar por 4 minutos, até ficarem claras e cremosas. Junte o óleo, o suco e as raspas de tangerina.","Acrescente os secos e misture com o fouet até ficar liso. A massa fica espessa nesta etapa.","Em tigela limpa e seca, bata as claras com o sal até espumarem, junte os 50 g de açúcar aos poucos e bata até picos firmes.","Incorpore um terço das claras à massa para soltá-la e misture com firmeza. Junte o restante com a espátula, de baixo para cima, sem bater.","Despeje na forma e asse por 33 a 35 minutos, sem abrir o forno nos primeiros 25 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar numa grade."],
["Qualquer gordura ou gema na tigela das claras impede que elas subam. Use tigela e batedor bem limpos.","Misture as claras com calma. Se o ar escapar, o bolo fica mais baixo, mas continua gostoso.","Confira no rótulo o fermento e a fécula."],
"Até 3 dias em recipiente fechado. Fica mais macio no segundo dia.","tangerina mexerica bergamota claras neve leve cítrico"),
RB(22,"Bolo de maracujá com glacê","Cítricos","Bolo macio de sabor ácido e perfumado, coberto com glacê de maracujá.","1 bolo de 22 cm com furo central (12 fatias)",25,38,"180 °C",
["150 ml (cerca de 3 maracujás)|polpa de maracujá peneirada, sem sementes, mais 45 ml para o glacê","3 unidades|ovos","180 g (cerca de 1 xícara)|açúcar","100 ml|óleo de girassol","200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","150 g (cerca de 1 e 1/4 de xícara)|açúcar de confeiteiro, para o glacê","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma de 22 cm com furo central e polvilhe com farinha de arroz.","Bata a polpa de maracujá com os ovos, o açúcar e o óleo no liquidificador por 1 minuto.","Peneire a farinha de arroz e a fécula numa tigela e despeje o líquido. Misture com o fouet até ficar liso. A massa deve ficar fluida.","Junte o fermento e misture com poucos movimentos.","Despeje na forma e asse por 36 a 38 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar por completo.","Misture o açúcar de confeiteiro com os 45 ml de polpa até obter um glacê espesso, que escorra devagar. Espalhe sobre o bolo frio e deixe firmar por 15 minutos."],
["Passe a polpa na peneira para retirar as sementes, que deixam o bolo amargo se forem trituradas.","Se usar polpa congelada, descongele e confira o rótulo: algumas contêm açúcar.","Confira no rótulo o açúcar de confeiteiro, a polpa e o fermento."],
"Até 3 dias em recipiente fechado, em local fresco.","maracujá polpa glacê ácido tropical liquidificador"),
RB(23,"Bolo de fubá cremoso","Fubá e milho","Bolo de fubá de massa líquida, com centro mais úmido e cremoso e perfume de queijo parmesão.","1 bolo de 22 cm de diâmetro (10 fatias)",15,48,"180 °C",
["3 unidades|ovos","350 ml|leite integral","80 ml|óleo de girassol","180 g (cerca de 1 xícara)|açúcar","200 g (1 e 1/3 de xícara)|fubá fino","30 g (3 colheres de sopa)|amido de milho","30 g (3 colheres de sopa)|queijo parmesão ralado","10 g (2 colheres de chá)|fermento químico em pó","1 colher de sopa|manteiga, para untar","1 colher de sopa|fubá, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com fubá.","No liquidificador, bata os ovos, o leite, o óleo e o açúcar por 1 minuto.","Junte o fubá, o amido e o queijo e bata por mais 1 minuto, até a massa ficar lisa.","Acrescente o fermento e misture com uma colher, sem bater.","Despeje na forma. A massa é bem líquida, como um creme fino.","Asse por 45 a 48 minutos. O bolo está pronto quando o topo estiver bem dourado e o centro firme ao toque leve, sem balançar. Um palito pode sair com um pouco de creme úmido.","Deixe esfriar 20 minutos na forma antes de desenformar. O bolo é mais úmido que os de farinha e firma ao esfriar."],
["Use fubá fino ou fubá mimoso. Fubá grosso deixa a massa arenosa.","O centro mais mole é uma característica da receita. Espere esfriar por completo antes de fatiar.","Confira no rótulo o fubá e o queijo, porque podem ser processados em locais que também processam trigo."],
"Até 3 dias na geladeira, em recipiente fechado. Sirva em temperatura ambiente.","fubá cremoso parmesão liquidificador mineiro milho"),
RB(24,"Bolo de fubá com goiabada","Fubá e milho","Bolo de fubá macio com camada de goiabada derretida no meio.","1 bolo de 22 cm de diâmetro (10 fatias)",20,42,"180 °C",
["180 g (1 e 1/4 de xícara)|fubá fino","80 g (1/2 xícara)|farinha de arroz branca","3 unidades|ovos","150 g (3/4 de xícara)|açúcar","100 ml|óleo de girassol","250 ml (1 xícara)|leite integral","12 g (1 colher de sopa rasa)|fermento químico em pó","150 g|goiabada em cubos de 1 cm","1 colher de chá|amido de milho, para os cubos de goiabada","1 colher de sopa|manteiga, para untar","1 colher de sopa|fubá, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com fubá.","Misture os cubos de goiabada com o amido de milho e reserve.","Bata os ovos com o açúcar por 3 minutos. Junte o óleo e o leite.","Peneire por cima o fubá, a farinha de arroz e o fermento e mexa até ficar liso. A massa deve ser fluida.","Despeje metade da massa na forma, espalhe a goiabada e cubra com o restante da massa.","Asse por 40 a 42 minutos, até dourar e um palito sair limpo, sem tocar na goiabada.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["A goiabada derrete no forno e pode grudar. Unte bem as laterais da forma.","Escolha goiabada firme, de corte. A cremosa derrete demais e sai da massa.","Confira no rótulo a goiabada, o fubá e o fermento."],
"Até 4 dias em recipiente fechado, em local fresco.","fubá goiabada romeu e julieta café da tarde recheio"),
RB(25,"Bolo de milho verde","Fubá e milho","Bolo de massa batida com milho verde, de sabor adocicado e textura úmida.","1 bolo de 22 cm de diâmetro (10 fatias)",20,40,"180 °C",
["200 g (1 lata, escorrida)|milho verde em conserva","3 unidades|ovos","200 ml|leite integral","100 ml|óleo de girassol","150 g (3/4 de xícara)|açúcar","140 g (1 xícara)|fubá fino","60 g (1/3 de xícara)|farinha de arroz branca","30 g (3 colheres de sopa)|queijo parmesão ralado","12 g (1 colher de sopa rasa)|fermento químico em pó","1 colher de sopa|manteiga, para untar","1 colher de sopa|fubá, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com fubá.","No liquidificador, bata o milho, os ovos, o leite, o óleo e o açúcar por 2 minutos, até a mistura ficar lisa.","Numa tigela, misture o fubá, a farinha de arroz e o queijo.","Despeje o líquido sobre os secos e mexa com o fouet até a massa ficar homogênea. Ela deve ser espessa e levemente granulada.","Acrescente o fermento e misture com poucos movimentos.","Despeje na forma e asse por 38 a 40 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["Escorra bem o milho. Se usar milho de espiga cozido, retire os grãos da espiga e use 200 g.","O bolo é mais úmido que o de fubá comum. Espere esfriar para cortar fatias inteiras.","Confira no rótulo o milho em conserva, o fubá, o queijo e o fermento."],
"Até 3 dias em recipiente fechado. Se quiser servir morno, aqueça no forno por 5 minutos.","milho verde fubá lata parmesão junino festa junina"),
RB(26,"Bolo de fubá com erva-doce","Fubá e milho","Bolo de fubá com leite aromatizado com erva-doce, de perfume suave e miolo macio.","1 bolo de 22 cm com furo central (12 fatias)",25,38,"180 °C",
["270 ml|leite integral","5 g (1 colher de sopa)|erva-doce em grãos","160 g (1 e 1/10 de xícara)|fubá fino","100 g (2/3 de xícara)|farinha de arroz branca","3 unidades|ovos","150 g (3/4 de xícara)|açúcar","80 ml|óleo de girassol","12 g (1 colher de sopa rasa)|fermento químico em pó","1 colher de sopa|manteiga, para untar","1 colher de sopa|fubá, para polvilhar a forma"],
["Aqueça o leite com a erva-doce até quase ferver, desligue, tampe e deixe em infusão por 10 minutos. Coe e meça 250 ml (acrescente leite frio se faltar). Deixe amornar.","Preaqueça o forno a 180 °C. Unte com manteiga uma forma de 22 cm com furo central e polvilhe com fubá.","Peneire o fubá, a farinha de arroz e o fermento.","Bata os ovos com o açúcar por 3 minutos. Junte o óleo e o leite coado e misture.","Acrescente os secos e mexa até ficar liso. A massa deve ser fluida.","Despeje na forma e asse por 36 a 38 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar numa grade."],
["Não deixe o leite ferver com a erva-doce, para o gosto não ficar amargo.","Se não gostar de pedaços de erva-doce, bata os grãos no liquidificador com o leite morno e coe.","Confira no rótulo a erva-doce, o fubá e o fermento."],
"Até 4 dias em recipiente fechado, em local fresco.","fubá erva-doce anis infusão leite furo"),
RB(27,"Bolo de fubá com queijo","Fubá e milho","Bolo de fubá adocicado com queijo curado ralado, que dá notas salgadas e uma crosta dourada.","1 bolo de 22 cm de diâmetro (10 fatias)",20,40,"180 °C",
["200 g (1 e 1/3 de xícara)|fubá fino","60 g (1/3 de xícara)|polvilho doce","3 unidades|ovos","120 g (3/5 de xícara)|açúcar","250 ml (1 xícara)|leite integral","80 ml|óleo de girassol","100 g|queijo minas meia cura ralado","12 g (1 colher de sopa rasa)|fermento químico em pó","1 colher de sopa|manteiga, para untar","1 colher de sopa|fubá, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com fubá.","Misture o fubá, o polvilho e o fermento numa tigela.","Bata os ovos com o açúcar por 3 minutos. Junte o leite e o óleo e misture.","Despeje o líquido sobre os secos e mexa até ficar liso. A massa deve ficar espessa e cair da colher em blocos.","Incorpore o queijo ralado com a espátula.","Despeje na forma e asse por 38 a 40 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar. É ótimo servido morno."],
["O queijo minas meia cura derrete sem escorrer. Queijos muito macios desmancham e deixam a massa úmida.","Para um bolo menos doce, reduza o açúcar para 100 g.","Confira no rótulo o queijo e o fubá."],
"Até 3 dias em recipiente fechado. Reaqueça no forno ou na frigideira antes de servir.","fubá queijo minas salgado doce lanche mineiro"),
RB(28,"Bolo de coco tradicional","Coco","Bolo macio, perfumado de coco, com leite de coco na massa e coco ralado por cima.","1 bolo de 22 cm de diâmetro (10 fatias)",20,40,"180 °C",
["3 unidades|ovos","200 g (1 xícara)|açúcar","100 ml|óleo de girassol","200 ml|leite de coco","200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","60 g (3/4 de xícara)|coco ralado seco sem açúcar","30 g (1/3 de xícara)|coco ralado seco sem açúcar, para o topo","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com farinha de arroz.","Bata os ovos com o açúcar por 4 minutos. Junte o óleo e o leite de coco.","Peneire a farinha de arroz, a fécula e o fermento sobre a mistura e mexa até ficar liso.","Incorpore os 60 g de coco ralado. A massa deve ser espessa e cremosa.","Despeje na forma e polvilhe os 30 g de coco ralado por cima.","Asse por 38 a 40 minutos, até o coco do topo dourar e um palito sair limpo.","Espere 10 minutos, desenforme com cuidado e deixe esfriar em grade."],
["Agite bem a lata de leite de coco antes de medir, para misturar a gordura que sobe.","Confira no rótulo o leite de coco e o coco ralado: alguns contêm aditivos e açúcar.","Se o coco do topo dourar rápido, cubra o bolo com papel-alumínio."],
"Até 4 dias em recipiente fechado, em local fresco.","coco ralado leite de coco tradicional clássico"),
RB(29,"Bolo de coco molhadinho","Coco","Bolo de assadeira regado com calda de leite condensado e leite de coco, bem úmido e gelado.","1 assadeira de 20 × 30 cm (12 pedaços)",25,30,"180 °C",
["3 unidades|ovos","150 g (3/4 de xícara)|açúcar","60 g (3 colheres de sopa)|manteiga derretida","120 ml|leite integral","180 g (1 e 1/5 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","40 g (1/2 xícara)|coco ralado seco sem açúcar, mais 40 g para o topo","200 g (cerca de 1/2 lata)|leite condensado","200 ml|leite de coco","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma assadeira de 20 × 30 cm e polvilhe com farinha de arroz.","Bata os ovos com o açúcar por 3 minutos. Junte a manteiga derretida e morna e o leite.","Peneire a farinha de arroz, a fécula e o fermento sobre a mistura e mexa até ficar liso. A massa deve ser fluida.","Incorpore os 40 g de coco ralado, despeje na assadeira e alise.","Asse por 28 a 30 minutos, até dourar e um palito sair limpo.","Misture o leite condensado com o leite de coco até ficar homogêneo.","Com o bolo ainda morno, fure toda a superfície com um garfo ou palito e regue com a calda aos poucos, esperando absorver.","Espalhe os 40 g de coco ralado do topo, cubra e leve à geladeira por pelo menos 2 horas antes de cortar."],
["A calda deve ser derramada devagar e em partes. O bolo absorve melhor se estiver morno.","Fica ainda melhor no dia seguinte, depois de a calda descansar.","Confira no rótulo o leite condensado, o leite de coco e o coco ralado."],
"Até 4 dias na geladeira, em recipiente fechado.","coco molhadinho calda leite condensado gelado assadeira"),
RB(30,"Bolo quindim","Coco","Bolo de gemas e coco, sem farinha, assado em banho-maria, de textura cremosa e topo dourado de coco.","1 bolo de 20 cm com furo central (10 fatias)",25,50,"170 °C",
["8 unidades|gemas","1 unidade|ovo inteiro","220 g (1 xícara e 2 colheres de sopa)|açúcar","100 g (1 e 1/4 de xícara)|coco ralado seco sem açúcar","150 ml|leite de coco","50 g (2 colheres de sopa e meia)|manteiga derretida","5 ml (1 colher de chá)|extrato de baunilha","1 colher de sopa|manteiga, para untar","1 colher de sopa|açúcar, para polvilhar a forma"],
["Preaqueça o forno a 170 °C. Unte com manteiga uma forma de 20 cm com furo central e polvilhe com açúcar. Ferva água para o banho-maria.","Numa tigela, misture com o fouet as gemas, o ovo, o açúcar, o leite de coco, a manteiga e a baunilha, sem bater em excesso, só até ficar homogêneo.","Junte o coco ralado e misture. Deixe descansar por 15 minutos.","Despeje na forma e coloque dentro de uma assadeira maior. Despeje a água fervente na assadeira até metade da altura da forma.","Asse por 45 a 50 minutos. O bolo está pronto quando o topo estiver dourado e o centro firme, com leve balanço apenas na parte mais interna.","Retire do banho-maria, espere esfriar por 30 minutos e leve à geladeira por pelo menos 3 horas.","Para desenformar, mergulhe o fundo da forma em água quente por 10 segundos, passe uma faca nas laterais e vire sobre um prato."],
["Bater muito incorpora ar e deixa o bolo cheio de furinhos. Misture devagar.","O coco sobe durante o preparo e o lado do coco fica por cima ao desenformar, como no quindim.","Confira no rótulo o coco ralado e o leite de coco."],
"Até 4 dias na geladeira, em recipiente fechado. Sirva gelado.","quindim gemas coco sem farinha banho-maria"),
RB(31,"Bolo de farinha de coco","Coco","Bolo denso e úmido, feito com farinha de coco, que absorve muito líquido e pede mais ovos que as outras farinhas.","1 bolo de 20 cm de diâmetro (8 fatias)",15,32,"170 °C",
["60 g (1/2 xícara)|farinha de coco","4 unidades|ovos","100 g (1/2 xícara)|açúcar","60 g (3 colheres de sopa)|manteiga derretida","200 ml|leite de coco","5 ml (1 colher de chá)|extrato de baunilha","4 g (1 colher de chá)|fermento químico em pó","1 pitada|sal","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de coco, para polvilhar a forma"],
["Preaqueça o forno a 170 °C. Unte com manteiga uma forma redonda de 20 cm e polvilhe com farinha de coco.","Bata os ovos com o açúcar por 3 minutos, até ficarem claros.","Junte a manteiga derretida e morna, o leite de coco e a baunilha e misture.","Acrescente a farinha de coco, o fermento e o sal e misture com o fouet até desfazer os grumos. A massa vai parecer líquida.","Deixe a massa descansar por 5 minutos. A farinha de coco absorve o líquido e a massa fica espessa e cremosa, como um creme.","Despeje na forma, alise o topo e asse por 30 a 32 minutos, até dourar e um palito sair limpo.","Espere 15 minutos, desenforme com cuidado e deixe esfriar. O bolo é frágil quando quente."],
["Não substitua a farinha de coco por outra farinha na mesma medida. Ela absorve muito mais líquido.","A farinha de coco pode ter grumos. Se necessário, passe a massa na peneira antes de assar.","Confira no rótulo a farinha de coco, o leite de coco e o fermento."],
"Até 4 dias na geladeira, em recipiente fechado. Sirva em temperatura ambiente.","farinha de coco leite de coco denso ovos"),
RB(32,"Bolo de mandioca","Raízes e legumes","Bolo de mandioca cozida batida no liquidificador, de massa densa, úmida e levemente elástica, com queijo parmesão.","1 bolo de 22 cm de diâmetro (10 fatias)",30,45,"180 °C",
["400 g|mandioca cozida, sem a fibra central, ainda morna","3 unidades|ovos","180 g (cerca de 1 xícara)|açúcar","80 ml|óleo de girassol","200 ml|leite integral","40 g (4 colheres de sopa)|queijo parmesão ralado","12 g (1 colher de sopa rasa)|fermento químico em pó","1 colher de sopa|manteiga, para untar","1 colher de sopa|polvilho doce, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com polvilho doce.","No liquidificador, bata a mandioca morna com os ovos, o leite, o óleo e o açúcar por 2 a 3 minutos, até ficar lisa e sem fiapos.","Junte o queijo e bata por mais 30 segundos.","Acrescente o fermento e misture com uma colher, sem bater.","Despeje na forma. A massa deve ser fluida, parecida com massa de panqueca grossa.","Asse por 42 a 45 minutos, até o topo dourar bem e o centro firmar. Um palito deve sair limpo ou com um pouco de massa úmida.","Espere 20 minutos antes de desenformar. Esse bolo firma ao esfriar."],
["Retire toda a fibra da mandioca. Pedaços de fibra deixam fiapos no bolo.","Use mandioca bem cozida e ainda morna, para bater lisa.","Confira no rótulo o queijo parmesão e o fermento."],
"Até 4 dias em recipiente fechado. Pode ser aquecido por 5 minutos no forno.","mandioca aipim macaxeira cozida liquidificador sem farinha parmesão"),
RB(33,"Bolo de cenoura com cobertura de chocolate","Raízes e legumes","Bolo clássico de cenoura de liquidificador, com cobertura de chocolate em calda, assado em assadeira.","1 assadeira de 20 × 30 cm (12 pedaços)",25,35,"180 °C",
["3 unidades (cerca de 300 g)|cenouras médias descascadas e cortadas em rodelas","3 unidades|ovos","120 ml (1/2 xícara)|óleo de girassol","220 g (1 e 1/10 de xícara)|açúcar","200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","150 g (3/4 de xícara)|açúcar, para a cobertura","25 g (3 colheres de sopa)|cacau em pó 100%, para a cobertura","20 g (1 colher de sopa)|manteiga, para a cobertura","100 ml|leite integral, para a cobertura","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma assadeira de 20 × 30 cm e polvilhe com farinha de arroz.","No liquidificador, bata a cenoura, os ovos, o óleo e o açúcar por 3 minutos, até a mistura ficar bem lisa e alaranjada.","Peneire a farinha de arroz e a fécula numa tigela grande, despeje o líquido e misture com o fouet. A massa deve ficar fluida.","Junte o fermento e misture com poucos movimentos.","Despeje na assadeira e asse por 33 a 35 minutos, até dourar e um palito sair limpo.","Para a cobertura, misture numa panela os 150 g de açúcar, o cacau, a manteiga e o leite. Leve ao fogo médio, mexendo, até ferver. Cozinhe por 3 minutos sem parar de mexer, até ficar levemente encorpada.","Espere a cobertura amornar por 5 minutos e despeje sobre o bolo ainda morno. Espere firmar antes de cortar."],
["Bata bem a cenoura. Pedaços grandes deixam grânulos na massa.","A cobertura engrossa ao esfriar. Use ainda morna para escorrer bem.","Confira no rótulo o cacau e o fermento."],
"Até 4 dias em recipiente fechado, em local fresco. Com a cobertura, guarde na geladeira em dias quentes.","cenoura cobertura chocolate liquidificador clássico assadeira"),
RB(34,"Bolo de batata-doce com nozes","Raízes e legumes","Bolo úmido de batata-doce, de sabor adocicado e natural, com nozes picadas na massa.","1 bolo de 22 cm de diâmetro (10 fatias)",30,43,"180 °C",
["300 g|batata-doce cozida, sem casca e amassada","3 unidades|ovos","150 g (3/4 de xícara)|açúcar mascavo","80 ml|óleo de girassol","100 ml|leite integral","160 g (1 xícara)|farinha de arroz branca","80 g (1/2 xícara)|polvilho doce","12 g (1 colher de sopa rasa)|fermento químico em pó","50 g (1/2 xícara)|nozes picadas","5 ml (1 colher de chá)|extrato de baunilha","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com farinha de arroz.","Misture a batata-doce ainda morna com o açúcar mascavo até desmanchar.","Junte os ovos, o óleo, o leite e a baunilha e misture bem com o fouet.","Peneire a farinha de arroz, o polvilho e o fermento sobre a mistura e mexa até ficar liso. A massa deve ser espessa e cair da colher em blocos moles.","Incorpore as nozes, reservando 2 colheres de sopa para o topo.","Despeje na forma, espalhe as nozes reservadas e asse por 40 a 43 minutos, até um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["Cozinhe a batata-doce no vapor ou na água, sem deixá-la encharcar. Escorra e amasse bem, sem pedaços.","Se preferir um bolo sem nozes, substitua por 50 g de coco ralado seco.","Confira no rótulo as nozes e o fermento. Há risco de contaminação cruzada em frutas secas a granel."],
"Até 4 dias em recipiente fechado. Congela bem em fatias por até 1 mês.","batata-doce nozes mascavo legumes úmido natural"),
RB(35,"Bolo de abóbora com castanhas","Raízes e legumes","Bolo macio de abóbora cabotiá, de cor dourada e sabor suave, com castanhas picadas.","1 bolo de 22 cm de diâmetro (10 fatias)",30,43,"180 °C",
["300 g|abóbora cabotiá cozida e amassada, bem escorrida","3 unidades|ovos","150 g (3/4 de xícara)|açúcar mascavo","80 ml|óleo de girassol","60 ml|leite integral","180 g (1 e 1/5 de xícara)|farinha de arroz branca","80 g (1/2 xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","60 g (1/2 xícara)|castanha-de-caju picada","5 ml (1 colher de chá)|extrato de baunilha","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com farinha de arroz.","Bata a abóbora amassada com o açúcar mascavo no liquidificador ou com um fouet, até ficar lisa.","Junte os ovos, o óleo, o leite e a baunilha e misture.","Peneire a farinha de arroz, a fécula e o fermento sobre a mistura e mexa até ficar liso. A massa deve ser espessa.","Incorpore a castanha com a espátula.","Despeje na forma e asse por 40 a 43 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["Escorra a abóbora cozida em peneira por 10 minutos. O excesso de água deixa o bolo pesado.","Abóbora cabotiá é mais doce e seca que a moranga. Se usar moranga, escorra por mais tempo.","Confira no rótulo a castanha e o fermento. Há risco de contaminação cruzada em frutas secas a granel."],
"Até 4 dias em recipiente fechado, em local fresco.","abóbora cabotiá jerimum castanha caju mascavo legumes"),
RB(36,"Bolo de inhame com iogurte","Raízes e legumes","Bolo macio e cremoso de inhame cozido, com iogurte e polvilho doce, de sabor suave.","1 bolo de 22 cm com furo central (12 fatias)",35,40,"180 °C",
["300 g|inhame cozido, sem casca e amassado como purê","3 unidades|ovos","150 g (3/4 de xícara)|açúcar","60 g (3 colheres de sopa)|manteiga derretida","120 g (cerca de 3/4 de pote)|iogurte natural integral","160 g (1 xícara)|farinha de arroz branca","70 g (1/2 xícara)|polvilho doce","12 g (1 colher de sopa rasa)|fermento químico em pó","raspas de 1 limão taiti|casca de limão","1 colher de sopa|manteiga, para untar","1 colher de sopa|polvilho doce, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma de 22 cm com furo central e polvilhe com polvilho doce.","Numa tigela, misture o purê de inhame morno com o açúcar até ficar liso.","Junte os ovos, a manteiga derretida, o iogurte e as raspas de limão e misture com o fouet.","Peneire a farinha de arroz, o polvilho e o fermento sobre a mistura e mexa até ficar liso. A massa deve ser espessa e cremosa.","Despeje na forma e alise.","Asse por 38 a 40 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["O inhame deve estar bem cozido e sem pedaços. Retire as partes fibrosas ao amassar.","Lave bem as mãos após descascar o inhame cru, pois ele pode irritar a pele. Descasque com luvas se preferir.","Confira no rótulo o iogurte e o fermento."],
"Até 4 dias em recipiente fechado. Pode ser guardado na geladeira em dias quentes.","inhame iogurte raízes polvilho limão furo"),
RB(37,"Bolo de canela com recheio de açúcar mascavo","Especiarias","Bolo macio de baunilha e canela, com uma camada de açúcar mascavo e canela no meio da massa.","1 bolo de 22 cm com furo central (12 fatias)",25,42,"180 °C",
["3 unidades|ovos","180 g (cerca de 1 xícara)|açúcar","100 ml|óleo de girassol","200 ml|leite integral","200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","4 g (1 colher de chá)|canela em pó, para a massa","60 g (1/3 de xícara)|açúcar mascavo, para o recheio","8 g (2 colheres de chá)|canela em pó, para o recheio","20 g (1 colher de sopa)|manteiga derretida, para o recheio","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma de 22 cm com furo central e polvilhe com farinha de arroz.","Misture o açúcar mascavo, os 8 g de canela e a manteiga derretida do recheio até formar uma farofa úmida. Reserve.","Bata os ovos com o açúcar por 4 minutos. Junte o óleo e o leite.","Peneire a farinha de arroz, a fécula, o fermento e os 4 g de canela sobre a mistura e mexa até ficar liso. A massa deve ser fluida.","Despeje metade da massa na forma, espalhe metade do recheio por cima, cubra com o restante da massa e termine com o recheio restante.","Com a ponta de uma faca, faça movimentos curtos na massa para marmorizar levemente.","Asse por 40 a 42 minutos, até um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["O recheio afunda um pouco durante o cozimento. Por isso o bolo tem uma camada visível no corte.","Para um sabor mais intenso, use canela em pau moída na hora.","Confira no rótulo a canela e o fermento."],
"Até 4 dias em recipiente fechado, em local fresco.","canela mascavo recheio especiarias café da tarde"),
RB(38,"Bolo de gengibre e melado","Especiarias","Bolo escuro e perfumado, de textura densa e úmida, com gengibre, canela e melado de cana.","1 bolo quadrado de 20 cm (12 pedaços)",25,38,"170 °C",
["2 unidades|ovos","80 g (cerca de 1/3 de xícara)|açúcar mascavo","120 g (cerca de 1/3 de xícara)|melado de cana","80 ml|óleo de girassol","200 ml|leite integral","160 g (1 xícara)|farinha de arroz integral","80 g (1/2 xícara)|fécula de batata","8 g (2 colheres de chá)|fermento químico em pó","3 g (1/2 colher de chá)|bicarbonato de sódio","15 g (1 colher de sopa)|gengibre fresco ralado","4 g (1 colher de chá)|gengibre em pó","3 g (1 colher de chá)|canela em pó","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 170 °C. Unte com manteiga uma forma quadrada de 20 cm e polvilhe com farinha de arroz.","Peneire a farinha integral, a fécula, o fermento, o bicarbonato, o gengibre em pó e a canela. Devolva à tigela os farelos que ficarem na peneira.","Misture com o fouet os ovos, o açúcar mascavo, o melado, o óleo, o leite e o gengibre fresco ralado.","Despeje o líquido sobre os secos e mexa até a massa ficar lisa. Ela é fluida e escura.","Despeje na forma e asse por 36 a 38 minutos, até um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar. O sabor melhora depois de algumas horas de descanso."],
["O melado pode ser substituído por mel, mas o bolo ficará mais claro e menos intenso.","Meça o melado com uma colher untada com óleo para ele escorrer inteiro.","Confira no rótulo o melado e as especiarias, pois alguns produtos podem conter aditivos."],
"Até 5 dias em recipiente fechado, em local fresco. O sabor melhora no segundo dia.","gengibre melado cana canela escuro especiarias gingerbread"),
RB(39,"Bolo de pera com cardamomo","Especiarias","Bolo de forma inglesa com cubos de pera e cardamomo moído, de perfume sofisticado e miolo macio.","1 bolo de 25 × 11 cm (10 fatias)",25,47,"170 °C",
["2 unidades (cerca de 250 g)|peras firmes em cubos de 1 cm","1 unidade (pequena, para o topo)|pera em fatias finas","3 unidades|ovos","150 g (3/4 de xícara)|açúcar","80 g (4 colheres de sopa)|manteiga derretida","100 g (1/2 pote)|iogurte natural integral","180 g (1 e 1/5 de xícara)|farinha de arroz branca","90 g (1/2 xícara e 1 colher de sopa)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","2 g (1 colher de chá)|cardamomo em pó","1 colher de sopa|açúcar, para o topo","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 170 °C. Unte com manteiga uma forma de 25 × 11 cm e polvilhe com farinha de arroz.","Bata os ovos com o açúcar por 3 minutos. Junte a manteiga derretida e morna e o iogurte.","Peneire a farinha de arroz, a fécula, o fermento e o cardamomo sobre a mistura e mexa até ficar liso. A massa deve ser espessa.","Incorpore os cubos de pera.","Despeje na forma, disponha as fatias de pera sobre a massa e polvilhe o açúcar do topo.","Asse por 44 a 47 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["Use peras firmes, como a williams ou a packham. Peras muito maduras desmancham.","O cardamomo é potente. Se não conhecer o sabor, comece com 1 g (1/2 colher de chá).","Confira no rótulo o cardamomo e o fermento."],
"Até 3 dias em recipiente fechado, em local fresco.","pera cardamomo especiarias fruta forma inglesa iogurte"),
RB(40,"Bolo de leite com noz-moscada","Especiarias","Bolo macio e amanteigado, enriquecido com leite em pó e perfumado com noz-moscada ralada na hora.","1 bolo de 22 cm com furo central (12 fatias)",20,36,"180 °C",
["3 unidades|ovos","150 g (3/4 de xícara)|açúcar","100 g (5 colheres de sopa)|manteiga derretida","200 ml|leite integral","40 g (4 colheres de sopa)|leite em pó integral","160 g (1 xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","1 g (1/4 de colher de chá, cerca de 4 raspadas)|noz-moscada ralada na hora","5 ml (1 colher de chá)|extrato de baunilha","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma de 22 cm com furo central e polvilhe com farinha de arroz.","Peneire a farinha de arroz, a fécula, o leite em pó, o fermento e a noz-moscada.","Bata os ovos com o açúcar por 4 minutos, até ficarem claros e volumosos.","Junte a manteiga derretida e morna, o leite e a baunilha e misture.","Acrescente os secos em duas vezes e mexa com o fouet só até incorporar. A massa deve ser espessa e cremosa.","Despeje na forma e asse por 34 a 36 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar em grade."],
["A noz-moscada é forte. Use pouco e rale na hora, para um perfume mais delicado.","O leite em pó deixa o miolo mais macio e a casca mais dourada.","Confira no rótulo o leite em pó, pois alguns produtos têm aditivos, e verifique a noz-moscada."],
"Até 4 dias em recipiente fechado, em local fresco.","leite em pó noz-moscada manteiga especiarias clássico furo"),
RBC("micro-ondas em potência alta, por cerca de 1 min 30 s",41,"Bolo de caneca de chocolate","Café e lanche","Bolo individual de chocolate, feito direto na caneca e pronto em poucos minutos no micro-ondas.","1 bolo individual em caneca de 300 ml",5,0,"",
["30 g (3 colheres de sopa)|farinha de arroz branca","10 g (1 colher de sopa)|cacau em pó 100%","30 g (2 colheres de sopa)|açúcar","1 unidade|ovo","45 ml (3 colheres de sopa)|leite integral","30 ml (2 colheres de sopa)|óleo de girassol","2 g (1/2 colher de chá)|fermento químico em pó","1 pitada|sal","1 colher de sopa|gotas de chocolate (opcional)"],
["Escolha uma caneca de 300 ml, de louça ou vidro próprio para micro-ondas, com altura suficiente para a massa dobrar de volume.","Na caneca, misture com um garfo a farinha de arroz, o cacau, o açúcar, o fermento e o sal.","Junte o ovo e misture até não restar farinha seca no fundo.","Acrescente o leite e o óleo e mexa até a massa ficar lisa. Ela deve ficar fluida, como massa de panqueca grossa. Se quiser, junte as gotas de chocolate.","Leve ao micro-ondas em potência alta por 1 minuto e 20 segundos a 1 minuto e 40 segundos. Em aparelhos de 700 a 800 W, pode ser necessário até 2 minutos.","O bolo está pronto quando o topo estiver firme e seco ao toque. Se ainda estiver úmido e brilhante no centro, leve por mais 15 segundos.","Espere 2 minutos antes de comer. Pode ser desenformado sobre um prato."],
["Se passar do ponto, o bolo fica borrachudo e seco. Prefira acrescentar poucos segundos de cada vez.","Cada micro-ondas tem potência diferente. Na primeira vez, observe o bolo de perto.","Confira no rótulo o cacau, o fermento e as gotas de chocolate."],
"Consuma na hora, ainda morno. Não é indicado guardar.","caneca micro-ondas individual chocolate rápido porção única"),
RBC("fogo baixo, tampada, por 12 a 15 minutos de um lado e 5 a 6 minutos do outro",42,"Bolo de banana de frigideira","Café e lanche","Bolo grosso de banana feito na frigideira, sem forno, macio por dentro e dourado por fora.","1 bolo de 20 cm (6 fatias)",15,0,"",
["200 g (2 bananas nanicas maduras)|banana amassada","2 unidades|ovos","50 g (1/4 de xícara)|açúcar","40 ml|óleo de girassol","100 ml|leite integral","100 g (2/3 de xícara)|farinha de arroz branca","40 g (1/4 de xícara)|fécula de batata","8 g (2 colheres de chá)|fermento químico em pó","2 g (1/2 colher de chá)|canela em pó","1 colher de chá|óleo, para untar a frigideira"],
["Unte com óleo uma frigideira antiaderente de 20 cm, com tampa, e aqueça em fogo baixo.","Numa tigela, misture com o fouet a banana amassada, os ovos, o açúcar, o óleo e o leite.","Peneire por cima a farinha de arroz, a fécula, o fermento e a canela e mexa até ficar liso. A massa deve ser espessa e cair da colher em blocos moles.","Despeje a massa na frigideira, alise e tampe.","Cozinhe em fogo baixo por 12 a 15 minutos, até a superfície secar e as bordas soltarem da frigideira. A parte de baixo deve estar dourada.","Com a ajuda de um prato do tamanho da frigideira, vire o bolo e doure o outro lado por 5 a 6 minutos, sem tampa.","O bolo está pronto quando um palito sair limpo do centro. Espere 5 minutos antes de cortar."],
["Fogo alto queima o fundo antes de o centro assar. Mantenha o fogo bem baixo e a tampa fechada.","Se tiver dificuldade para virar, deslize o bolo para um prato e devolva à frigideira com o lado cru para baixo.","Confira no rótulo a canela e o fermento."],
"Até 2 dias em recipiente fechado. Pode ser aquecido por 20 segundos no micro-ondas.","frigideira sem forno banana canela rápido panela lanche"),
RB(43,"Cupcakes de baunilha com gotas de chocolate","Café e lanche","Muffins macios e pouco doces, com gotas de chocolate, para o lanche ou a lancheira.","12 muffins",20,22,"180 °C",
["2 unidades|ovos","130 g (2/3 de xícara)|açúcar","80 ml|óleo de girassol","130 ml|leite integral","100 g (cerca de 2/3 de pote)|iogurte natural integral","150 g (1 xícara)|farinha de arroz branca","80 g (1/2 xícara)|fécula de batata","10 g (2 colheres de chá)|fermento químico em pó","5 ml (1 colher de chá)|extrato de baunilha","60 g (1/3 de xícara)|gotas de chocolate meio amargo","1 colher de chá|amido de milho, para enfarinhar as gotas","12 unidades|forminhas de papel para muffin"],
["Preaqueça o forno a 180 °C. Forre uma forma de 12 cavidades para muffins com as forminhas de papel.","Misture as gotas de chocolate com o amido de milho e reserve.","Na tigela, misture com o fouet os ovos, o açúcar, o óleo, o leite, o iogurte e a baunilha.","Peneire a farinha de arroz, a fécula e o fermento sobre a mistura e mexa até ficar liso. A massa deve ser espessa e cair da colher em blocos moles.","Incorpore as gotas de chocolate.","Distribua a massa nas forminhas, enchendo cerca de 2/3 da altura de cada uma.","Asse por 20 a 22 minutos, até dourar e um palito sair limpo.","Deixe esfriar por 5 minutos na forma e transfira para uma grade."],
["Encher as forminhas até a borda faz a massa transbordar. Duas colheres de sopa cheias por forminha costumam bastar.","Para variar, troque as gotas por pedaços de banana ou morango.","Confira no rótulo as gotas de chocolate, o iogurte e o fermento."],
"Até 3 dias em recipiente fechado. Congela bem por até 1 mês.","muffin cupcake gotas chocolate lancheira individual baunilha"),
RB(44,"Bolo de iogurte com sementes","Café e lanche","Bolo de forma inglesa com chia, linhaça e girassol, de miolo úmido e textura crocante das sementes.","1 bolo de 25 × 11 cm (10 fatias)",25,42,"170 °C",
["15 g (1 colher de sopa)|chia","20 g (2 colheres de sopa)|linhaça dourada triturada","20 g (2 colheres de sopa)|sementes de girassol sem sal","170 g (1 pote)|iogurte natural integral","50 ml|leite integral","3 unidades|ovos","120 g (3/5 de xícara)|açúcar mascavo","80 ml|óleo de girassol","150 g (1 xícara)|farinha de arroz integral","80 g (1/2 xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Misture a chia, a linhaça, o iogurte e o leite numa tigela e deixe descansar por 10 minutos, até ficar espesso.","Preaqueça o forno a 170 °C. Unte com manteiga uma forma de 25 × 11 cm e polvilhe com farinha de arroz.","Junte à mistura de sementes os ovos, o açúcar mascavo e o óleo e misture com o fouet.","Peneire a farinha integral, a fécula e o fermento sobre a mistura e mexa até ficar liso. Devolva à tigela os farelos que ficarem na peneira. A massa deve ser espessa e cair da colher em blocos.","Despeje na forma e espalhe as sementes de girassol por cima.","Asse por 40 a 42 minutos, até dourar e um palito sair limpo.","Espere 10 minutos, desenforme e deixe esfriar em grade antes de fatiar."],
["A chia e a linhaça absorvem líquido. Se a massa ficar muito dura, junte 1 colher de sopa de leite.","Linhaça triturada fica mais saborosa e rende mais fibras que a inteira. Guarde-a na geladeira.","Confira no rótulo as sementes e a linhaça, pelo risco de contaminação cruzada, e o fermento."],
"Até 4 dias em recipiente fechado. Fatias podem ser congeladas por até 1 mês.","sementes chia linhaça girassol integral iogurte fibras forma inglesa"),
RB(45,"Bolo de amêndoas e laranja","Café e lanche","Bolo de farinha de amêndoas com claras em neve, perfumado de laranja, de miolo úmido e macio.","1 bolo de 20 cm de diâmetro (8 fatias)",30,38,"170 °C",
["180 g (1 e 3/4 de xícara)|farinha de amêndoas","4 unidades|ovos, separados","140 g (cerca de 3/4 de xícara)|açúcar","80 g (4 colheres de sopa)|manteiga derretida","raspas de 1 laranja (só a parte alaranjada)|casca de laranja","40 ml (cerca de 3 colheres de sopa)|suco de laranja","6 g (1 colher de chá bem cheia)|fermento químico em pó","1 pitada|sal","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de amêndoas, para polvilhar a forma"],
["Preaqueça o forno a 170 °C. Unte com manteiga uma forma de 20 cm de fundo removível, forre o fundo com papel-manteiga e polvilhe as laterais com farinha de amêndoas.","Misture a farinha de amêndoas com o fermento.","Bata as gemas com 100 g do açúcar por 4 minutos, até ficarem claras. Junte a manteiga derretida e morna, as raspas e o suco de laranja.","Acrescente a farinha de amêndoas e misture até ficar homogêneo. A massa fica espessa, mais firme que massa de bolo comum.","Em tigela limpa e seca, bata as claras com o sal até espumarem, junte os 40 g de açúcar restantes aos poucos e bata até picos moles.","Incorpore um terço das claras à massa para soltá-la e misture com firmeza. Junte o restante delicadamente, de baixo para cima.","Despeje na forma e asse por 36 a 38 minutos, até dourar e um palito sair limpo.","Deixe esfriar 15 minutos na forma, solte as laterais e desenforme com cuidado."],
["O bolo é mais frágil que os de farinha de arroz. Espere amornar antes de desenformar.","Troque a laranja por limão-siciliano se preferir um sabor mais ácido.","Confira no rótulo a farinha de amêndoas, pelo risco de contaminação cruzada, e o fermento. Não indicado para pessoas com alergia a oleaginosas."],
"Até 4 dias em recipiente fechado, em local fresco, ou 5 dias na geladeira.","amêndoas farinha de amêndoas laranja claras sem farinha oleaginosas"),
RB(46,"Bolo de chocolate com recheio de brigadeiro e ganache","Especiais","Bolo alto de duas camadas de chocolate, recheado com brigadeiro e coberto com ganache, para ocasiões especiais.","1 bolo de 22 cm com duas camadas (12 fatias)",60,38,"180 °C",
["4 unidades|ovos, separados","150 g (3/4 de xícara)|açúcar, para as gemas","50 g (1/4 de xícara)|açúcar, para as claras","100 ml|óleo de girassol","150 ml|leite integral","40 g (1/2 xícara)|cacau em pó 100%","160 g (1 xícara)|farinha de arroz branca","80 g (1/2 xícara)|fécula de batata","10 g (2 colheres de chá)|fermento químico em pó","395 g (1 lata)|leite condensado, para o recheio","30 g (3 colheres de sopa)|cacau em pó 100%, para o recheio","20 g (1 colher de sopa)|manteiga, para o recheio","50 ml|creme de leite fresco, para o recheio","200 g|chocolate meio amargo picado, para a ganache","200 g (1 caixinha)|creme de leite, para a ganache","1 colher de sopa|manteiga, para untar","1 colher de sopa|cacau em pó, para polvilhar a forma"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma redonda de 22 cm de fundo removível, forre o fundo com papel-manteiga e polvilhe as laterais com cacau.","Peneire a farinha de arroz, a fécula, os 40 g de cacau e o fermento.","Bata as gemas com os 150 g de açúcar por 4 minutos, até ficarem claras. Junte o óleo e o leite.","Acrescente os secos e misture até ficar liso. A massa fica espessa.","Em tigela limpa e seca, bata as claras até espumarem, junte os 50 g de açúcar aos poucos e bata até picos firmes. Incorpore um terço à massa e misture com firmeza, depois junte o restante delicadamente.","Despeje na forma e asse por 36 a 38 minutos, até um palito sair limpo. Espere 10 minutos, desenforme e deixe esfriar por completo.","Para o recheio, leve ao fogo baixo o leite condensado, os 30 g de cacau, a manteiga e o creme de leite fresco, mexendo sem parar por 8 a 10 minutos, até aparecer o fundo da panela. Deixe esfriar até ficar espalhável.","Para a ganache, aqueça o creme de leite até começar a ferver nas bordas, despeje sobre o chocolate picado, espere 2 minutos e mexa até ficar liso. Deixe firmar por cerca de 30 minutos, até a consistência de creme espesso.","Corte o bolo frio ao meio na horizontal. Recheie com o brigadeiro, tampe e cubra o topo e as laterais com a ganache. Leve à geladeira por 30 minutos para firmar."],
["Bolo frio é essencial para cortar e rechear sem esfarelar. Prepare-o no dia anterior, se possível.","Se a ganache endurecer demais, aqueça no micro-ondas por 5 segundos e mexa.","Confira no rótulo o chocolate, o cacau, o leite condensado e o creme de leite."],
"Até 4 dias na geladeira, em recipiente fechado. Retire 30 minutos antes de servir.","chocolate festa aniversário brigadeiro ganache recheio duas camadas"),
RB(47,"Rocambole de doce de leite","Especiais","Rocambole de massa fina e macia, enrolado com doce de leite, que dispensa fermento.","1 rocambole (10 fatias)",30,14,"180 °C",
["4 unidades|ovos, separados","100 g (1/2 xícara)|açúcar, dividido em duas partes","80 g (cerca de 2/3 de xícara)|amido de milho","20 g (2 colheres de sopa)|farinha de arroz branca","5 ml (1 colher de chá)|extrato de baunilha","1 pitada|sal","300 g (1 pote)|doce de leite pastoso","2 colheres de sopa|açúcar, para polvilhar o papel","1 colher de chá|manteiga, para untar"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma assadeira de 25 × 35 cm e forre com papel-manteiga, deixando sobrar nas pontas.","Peneire duas vezes juntos o amido de milho e a farinha de arroz.","Bata as gemas com 50 g do açúcar e a baunilha por 5 minutos, até ficarem claras e volumosas.","Em tigela limpa e seca, bata as claras com o sal até espumarem, junte os outros 50 g de açúcar aos poucos e bata até picos firmes.","Incorpore um terço das claras às gemas, peneire por cima os secos e misture com a espátula. Junte o restante das claras delicadamente.","Espalhe a massa de modo uniforme na assadeira, com cerca de 1 cm de altura, e asse por 12 a 14 minutos, até dourar de leve e ficar macia ao toque.","Polvilhe o açúcar sobre uma folha de papel-manteiga e vire a massa sobre ela ainda quente. Retire o papel de baixo e enrole a massa com o papel por dentro, a partir da ponta mais estreita. Deixe esfriar enrolada.","Desenrole com cuidado, retire o papel, espalhe o doce de leite e enrole de novo, sem o papel, apertando levemente."],
["Enrolar a massa ainda quente evita que ela rache. Não espere esfriar para fazer o primeiro enrolamento.","Se o doce de leite estiver duro, aqueça por 10 segundos no micro-ondas, para espalhar.","Confira no rótulo o doce de leite, que pode conter aditivos, e o amido."],
"Até 3 dias na geladeira, em recipiente fechado. Sirva em temperatura ambiente.","rocambole doce de leite enrolado ovos sem fermento festa"),
RB(48,"Cheesecake assado de goiabada","Especiais","Torta cremosa assada, com base de amêndoas e cobertura de calda de goiabada.","1 cheesecake de 20 cm (10 fatias)",35,50,"160 °C",
["120 g (1 e 1/4 de xícara)|farinha de amêndoas, para a base","30 g (2 colheres de sopa)|açúcar, para a base","50 g (2 colheres de sopa e meia)|manteiga derretida, para a base","500 g (2 embalagens)|cream cheese, em temperatura ambiente","100 g (1/2 xícara)|açúcar, para o recheio","3 unidades|ovos","100 g (1/2 caixinha)|creme de leite fresco","5 ml (1 colher de chá)|extrato de baunilha","200 g|goiabada cremosa, para a cobertura","60 ml|água, para a cobertura","1 colher de sopa|manteiga, para untar"],
["Preaqueça o forno a 180 °C. Unte com manteiga uma forma de 20 cm de fundo removível e forre o fundo com papel-manteiga.","Misture a farinha de amêndoas, os 30 g de açúcar e a manteiga derretida até formar uma farofa úmida. Pressione no fundo da forma e asse por 10 minutos. Retire e baixe o forno para 160 °C.","Bata o cream cheese com os 100 g de açúcar em velocidade baixa até ficar liso, sem incorporar ar demais.","Junte os ovos, um de cada vez, o creme de leite e a baunilha, batendo só até misturar.","Despeje o recheio sobre a base e bata a forma levemente na bancada para soltar as bolhas.","Asse a 160 °C por 40 a 45 minutos, até as bordas firmarem e o centro ainda tremer levemente. Desligue o forno, entreabra a porta e deixe o cheesecake esfriar lá dentro por 1 hora.","Retire, espere esfriar por completo e leve à geladeira por pelo menos 6 horas.","Para a cobertura, aqueça a goiabada com a água em fogo baixo, mexendo, até ficar lisa e um pouco fluida. Espere amornar e espalhe sobre o cheesecake gelado."],
["Todos os ingredientes do recheio devem estar em temperatura ambiente, para a massa ficar lisa.","Ovos batidos em excesso fazem o cheesecake inchar e rachar. Bata só até misturar.","Confira no rótulo o cream cheese, a goiabada e a farinha de amêndoas. Não indicado para pessoas com alergia a oleaginosas."],
"Até 5 dias na geladeira, em recipiente fechado. Sirva gelado.","cheesecake goiabada cream cheese torta assada amêndoas romeu e julieta"),
RB(49,"Bolo de baunilha com chantilly e morangos","Especiais","Bolo de duas camadas finas com chantilly e morangos frescos, de acabamento simples e visual de bolo de festa.","1 bolo de 18 cm com duas camadas (10 fatias)",50,27,"180 °C",
["120 g (6 colheres de sopa)|manteiga em temperatura ambiente","180 g (cerca de 1 xícara)|açúcar","3 unidades|ovos","200 g (1 e 1/3 de xícara)|farinha de arroz branca","100 g (2/3 de xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","180 ml|leite integral","5 ml (1 colher de chá)|extrato de baunilha","300 ml|creme de leite fresco gelado (mínimo 35% de gordura)","40 g (4 colheres de sopa)|açúcar de confeiteiro, para o chantilly","5 ml (1 colher de chá)|extrato de baunilha, para o chantilly","250 g|morangos lavados e secos, mais alguns para decorar","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar as formas"],
["Preaqueça o forno a 180 °C. Unte com manteiga duas formas redondas de 18 cm e polvilhe com farinha de arroz.","Peneire a farinha de arroz, a fécula e o fermento.","Na batedeira, bata a manteiga com o açúcar por 4 a 5 minutos, até virar um creme claro e fofo.","Junte os ovos um a um, batendo 1 minuto após cada um. Acrescente a baunilha.","Junte os secos em três vezes, alternando com o leite em duas vezes, em velocidade baixa. A massa deve ficar espessa e cremosa.","Divida igualmente entre as duas formas e asse por 25 a 27 minutos, até um palito sair limpo. Espere 10 minutos, desenforme e deixe esfriar por completo.","Bata o creme de leite gelado com o açúcar de confeiteiro e a baunilha do chantilly até picos moles, que dobrem sem escorrer. Não bata além disso, para não virar manteiga. Leve à geladeira.","Corte os morangos em fatias. Coloque uma camada de bolo no prato, cubra com metade do chantilly e metade dos morangos. Repita com a segunda camada e decore o topo com o restante e morangos inteiros."],
["O creme de leite e a tigela devem estar bem gelados. Em dias quentes, leve a tigela por 15 minutos ao congelador.","Monte o bolo perto do horário de servir, para os morangos não soltarem água no chantilly.","Confira no rótulo o creme de leite, o açúcar de confeiteiro e o fermento."],
"Até 2 dias na geladeira, em recipiente fechado. Retire 15 minutos antes de servir.","chantilly morango naked cake aniversário duas camadas festa baunilha"),
RB(50,"Bolo de nozes com calda de caramelo","Especiais","Bolo de massa macia, com nozes moídas e picadas, coberto com calda de caramelo cremosa.","1 bolo de 22 cm de diâmetro (10 fatias)",35,40,"170 °C",
["100 g (1 xícara)|nozes picadas grosseiramente","60 g (cerca de 1/2 xícara)|nozes moídas","3 unidades|ovos","150 g (3/4 de xícara)|açúcar mascavo","100 g (5 colheres de sopa)|manteiga derretida","150 ml|leite integral","150 g (1 xícara)|farinha de arroz branca","80 g (1/2 xícara)|fécula de batata","12 g (1 colher de sopa rasa)|fermento químico em pó","5 ml (1 colher de chá)|extrato de baunilha","150 g (3/4 de xícara)|açúcar, para a calda","40 ml|água, para a calda","120 ml|creme de leite fresco, para a calda","30 g (1 colher de sopa cheia)|manteiga, para a calda","1 colher de sopa|manteiga, para untar","1 colher de sopa|farinha de arroz, para polvilhar a forma"],
["Preaqueça o forno a 170 °C. Unte com manteiga uma forma redonda de 22 cm e polvilhe com farinha de arroz.","Peneire a farinha de arroz, a fécula e o fermento e misture com as nozes moídas.","Bata os ovos com o açúcar mascavo por 4 minutos. Junte a manteiga derretida e morna, o leite e a baunilha.","Acrescente os secos e mexa até ficar liso. A massa deve ser espessa e cair da colher em blocos moles.","Incorpore as nozes picadas, reservando 2 colheres de sopa para o topo.","Despeje na forma, espalhe as nozes reservadas e asse por 38 a 40 minutos, até dourar e um palito sair limpo. Espere 10 minutos, desenforme e deixe esfriar.","Para a calda, leve ao fogo médio os 150 g de açúcar com a água, sem mexer, por 6 a 8 minutos, até ficar âmbar. Tire do fogo e junte o creme de leite, que deve estar morno, aos poucos e com cuidado, pois espirra e borbulha.","Junte a manteiga, mexa até ficar liso e deixe amornar por 10 minutos. Despeje sobre o bolo e deixe firmar um pouco antes de cortar."],
["O caramelo é muito quente. Use uma panela alta e afaste o rosto ao juntar o creme de leite.","A calda engrossa ao esfriar. Se endurecer, aqueça por 10 segundos no micro-ondas.","Confira no rótulo as nozes, pelo risco de contaminação cruzada, e o creme de leite. Não indicado para pessoas com alergia a oleaginosas."],
"Até 4 dias em recipiente fechado, em local fresco. Com a calda, mantenha na geladeira em dias quentes.","nozes caramelo calda mascavo festa oleaginosas sobremesa"),
];
